-- POVO AI Guidance: bronze reference tables (ARCHITECTURE.md section 4.1).
--
-- The app only reads these tables. They are regenerated by
-- seed/generate_seed_data.py and loaded by scripts/load_seed_data.py, which
-- reads this file to learn each column's type, so keep one column per line in
-- the form  NAME TYPE [NOT NULL] COMMENT '...'.
--
-- Delta does not enforce primary keys; the keys named in the comments are
-- logical. NOT NULL is only declared on key columns.
-- Only the two fact tables are clustered: they are the only ones queried by
-- territory at volume, and the rest are a few hundred rows at most.

CREATE TABLE IF NOT EXISTS ${catalog}.${bronze_schema}.DIM_TERRITORY (
  TERRITORY_ID STRING NOT NULL COMMENT 'Territory key, e.g. NE-POR',
  TERRITORY_NAME STRING COMMENT 'Display name, e.g. Portland, ME territory',
  CITY STRING COMMENT 'Anchor city of the territory',
  STATE STRING COMMENT 'Two-letter state code of the anchor city',
  REGION STRING COMMENT 'Sales region, e.g. Northeast',
  TIME_ZONE STRING COMMENT 'IANA time zone, e.g. America/New_York'
) USING DELTA
COMMENT 'Sales territories. Logical key TERRITORY_ID.';

CREATE TABLE IF NOT EXISTS ${catalog}.${bronze_schema}.DIM_EMPLOYEE (
  EMPLOYEE_ID STRING NOT NULL COMMENT 'Employee ID, e.g. p250544',
  NETWORK_ID STRING COMMENT 'Network ID, e.g. 3351',
  USERNAME STRING COMMENT 'Login name matched against the Posit identity header, e.g. vturano',
  EMAIL STRING COMMENT 'Work email, fallback match for the identity header',
  FIRST_NAME STRING COMMENT 'First name',
  LAST_NAME STRING COMMENT 'Last name',
  FULL_NAME STRING COMMENT 'First and last name',
  INITIALS STRING COMMENT 'Initials shown in the avatar',
  BUSINESS_UNIT STRING COMMENT 'Business unit, e.g. COMMERCIAL',
  ROLE_CODE STRING COMMENT 'REP or MANAGER; drives permissions',
  ROLE_TITLE STRING COMMENT 'POVO Sales Representative or Manager, Field Sales Enablement',
  ACCESS_LEVEL STRING COMMENT 'Access description shown in the impersonation card',
  ACCESS_REGIONS STRING COMMENT 'Regions the employee can see, e.g. Northeast',
  HOME_TERRITORY_ID STRING COMMENT 'Territory that scopes every data query for this employee',
  IS_ACTIVE BOOLEAN COMMENT 'False blocks access with 403'
) USING DELTA
COMMENT 'Employees who can use the app (reps and managers). Logical key EMPLOYEE_ID.';

CREATE TABLE IF NOT EXISTS ${catalog}.${bronze_schema}.DIM_ACCOUNT (
  ACCOUNT_ID STRING NOT NULL COMMENT 'Account key',
  TERRITORY_ID STRING COMMENT 'Territory the account belongs to',
  ACCOUNT_NAME STRING COMMENT 'Practice or site name',
  CITY STRING COMMENT 'City',
  STATE STRING COMMENT 'Two-letter state code',
  ZIP STRING COMMENT 'Five-digit ZIP code, kept as text to preserve leading zeros',
  CLAIMS_HS_PATIENTS INT COMMENT 'HS patients at the site from account-level claims, last 12 months',
  CLAIMS_POVO_PATIENTS INT COMMENT 'POVO patients at the site from account-level claims',
  CLAIMS_MAIN_FOCUS STRING COMMENT 'Competitive focus code with the highest HS volume at the site',
  IS_CLAIMS_ONLY BOOLEAN COMMENT 'True when claims show HS patients but no treating HCP is affiliated'
) USING DELTA
COMMENT 'Accounts (practices and sites). Logical key ACCOUNT_ID.';

CREATE TABLE IF NOT EXISTS ${catalog}.${bronze_schema}.DIM_HCP (
  HCP_ID STRING NOT NULL COMMENT 'HCP key, e.g. H000123',
  NPI STRING COMMENT 'National Provider Identifier (dummy, Luhn-valid)',
  FIRST_NAME STRING COMMENT 'First name',
  LAST_NAME STRING COMMENT 'Last name',
  DEGREE STRING COMMENT 'MD, DO, NP or PA',
  ROLE_TYPE STRING COMMENT 'HCP (physician), NP or PA',
  SPECIALTY STRING COMMENT 'Dermatology, Rheumatology or General Surgery',
  ACCOUNT_ID STRING COMMENT 'Primary account',
  PARENT_HCP_ID STRING COMMENT 'Affiliated physician for an NP or PA; null for a physician',
  TERRITORY_ID STRING COMMENT 'Territory',
  CITY STRING COMMENT 'City of the primary account',
  STATE STRING COMMENT 'State of the primary account',
  ZIP STRING COMMENT 'ZIP of the primary account'
) USING DELTA
COMMENT 'Call targets: physicians and their affiliated NPs and PAs. Logical key HCP_ID.';

CREATE TABLE IF NOT EXISTS ${catalog}.${bronze_schema}.FCT_HCP_METRICS (
  HCP_ID STRING NOT NULL COMMENT 'HCP',
  AS_OF_DATE DATE NOT NULL COMMENT 'Snapshot date; the app uses the latest per HCP',
  HS_PATIENTS_12M INT COMMENT 'HS patients seen in the last 12 months',
  HS_VISITS_PER_MONTH INT COMMENT 'Average HS visits a month',
  JAK_PATIENTS INT COMMENT 'HS patients on an oral JAK inhibitor; above 0 means a JAK user',
  POVO_PATIENTS INT COMMENT 'POVO patients; equals the NEW_PATIENT events for the HCP',
  INCYTECARES_ENROLLED_PATIENTS INT COMMENT 'Patients enrolled in IncyteCARES (enrollment forms received)'
) USING DELTA
COMMENT 'HCP volume and POVO metrics by snapshot. Logical key HCP_ID + AS_OF_DATE.';

CREATE TABLE IF NOT EXISTS ${catalog}.${bronze_schema}.DIM_CALL_PLAN_TARGET (
  PLAN_YEAR INT NOT NULL COMMENT 'Call plan year',
  TERRITORY_ID STRING NOT NULL COMMENT 'Territory',
  HCP_ID STRING NOT NULL COMMENT 'HCP',
  DECILE INT COMMENT 'POVO weighted index decile, 1 to 10',
  TIER_CODE STRING COMMENT 'SH, MED or LOW; null for decile 1',
  SEGMENT_CODE STRING COMMENT 'imm, conv or exp',
  COMPETITIVE_FOCUS STRING COMMENT 'cosentyx, bimzelx, humira, jak or conventional',
  IS_IN_CALL_PLAN BOOLEAN COMMENT 'True for deciles 2 to 10',
  HS_RANK INT COMMENT 'Rank by HS volume within the territory, 1 = highest'
) USING DELTA
COMMENT 'POVO targets and their call-plan attributes. Logical key PLAN_YEAR + TERRITORY_ID + HCP_ID.';

CREATE TABLE IF NOT EXISTS ${catalog}.${bronze_schema}.REF_TIER (
  TIER_CODE STRING NOT NULL COMMENT 'SH, MED or LOW',
  TIER_NAME STRING COMMENT 'Super High, Medium or Low',
  DECILE_MIN INT COMMENT 'Lowest decile in the tier',
  DECILE_MAX INT COMMENT 'Highest decile in the tier',
  CALLS_PER_YEAR INT COMMENT 'Planned calls a year per target',
  REACH_GOAL_PCT INT COMMENT 'Reach goal in percent',
  SORT_ORDER INT COMMENT 'Display order'
) USING DELTA
COMMENT 'Call-plan tiers. Logical key TIER_CODE.';

CREATE TABLE IF NOT EXISTS ${catalog}.${bronze_schema}.REF_SEGMENT (
  SEGMENT_CODE STRING NOT NULL COMMENT 'imm, conv or exp',
  SHORT_NAME STRING COMMENT 'Immediate, Conversion or Expansion',
  FULL_NAME STRING COMMENT 'Full segment name',
  DESCRIPTION STRING COMMENT 'Segment description',
  COLOR_HEX STRING COMMENT 'Chart colour',
  ARCHETYPE_NAME STRING COMMENT 'Patient archetype the rep discusses for this segment, e.g. Tara',
  ARCHETYPE_DESC STRING COMMENT 'Archetype description, e.g. losing control on a biologic',
  SORT_ORDER INT COMMENT 'Display order'
) USING DELTA
COMMENT 'Target segments. Logical key SEGMENT_CODE.';

CREATE TABLE IF NOT EXISTS ${catalog}.${bronze_schema}.REF_KPI_METRIC (
  METRIC_CODE STRING NOT NULL COMMENT 'PEF, NRX or NEW_PATIENTS (matches FCT_TERRITORY_GOAL.METRIC_CODE)',
  EVENT_TYPE STRING COMMENT 'FCT_POVO_ACTIVITY.EVENT_TYPE counted as the actual (PEF, NRX, NEW_PATIENT)',
  TITLE STRING COMMENT 'KPI card title, e.g. Patient Enrollment Forms',
  UNIT STRING COMMENT 'Unit shown after the numbers, e.g. PEFs',
  SORT_ORDER INT COMMENT 'Card order'
) USING DELTA
COMMENT 'Territory Performance KPI definitions. Logical key METRIC_CODE.';

CREATE TABLE IF NOT EXISTS ${catalog}.${bronze_schema}.REF_KPI_PARAMETER (
  PARAM_CODE STRING NOT NULL COMMENT 'PAID_PERSISTENCE, PENDING_ON_THERAPY or BRIDGE_SHARE',
  PARAM_VALUE DOUBLE COMMENT 'Rate between 0 and 1',
  DESCRIPTION STRING COMMENT 'What the rate means',
  SORT_ORDER INT COMMENT 'Display order'
) USING DELTA
COMMENT 'Rates behind the Total on POVO split (Paid / Bridge / Free Trial). Logical key PARAM_CODE.';

CREATE TABLE IF NOT EXISTS ${catalog}.${bronze_schema}.REF_INTERACTION_CHANNEL (
  CHANNEL_CODE STRING NOT NULL COMMENT 'rep, adfa, opz, msl, spkr or pr (matches FCT_INTERACTION.CHANNEL_CODE)',
  TYPE_LABEL STRING COMMENT 'Interaction card title, e.g. Direct call',
  TEAM_LABEL STRING COMMENT 'Team shown on the filter chip, e.g. POVO Sales',
  SORT_ORDER INT COMMENT 'Chip order'
) USING DELTA
COMMENT 'Interaction channels and their teams. Logical key CHANNEL_CODE.';

CREATE TABLE IF NOT EXISTS ${catalog}.${bronze_schema}.REF_COMPETITIVE_FOCUS (
  FOCUS_CODE STRING NOT NULL COMMENT 'cosentyx, bimzelx, humira, jak or conventional',
  LABEL STRING COMMENT 'Display label',
  COLOR_HEX STRING COMMENT 'Tag colour',
  SORT_ORDER INT COMMENT 'Display order'
) USING DELTA
COMMENT 'Competitive focus values. Logical key FOCUS_CODE.';

CREATE TABLE IF NOT EXISTS ${catalog}.${bronze_schema}.FCT_INTERACTION (
  INTERACTION_ID STRING NOT NULL COMMENT 'Interaction key',
  HCP_ID STRING COMMENT 'HCP',
  TERRITORY_ID STRING COMMENT 'Territory',
  EMPLOYEE_ID STRING COMMENT 'The rep for channel rep; null for other teams',
  INTERACTION_DATE DATE COMMENT 'Date of the interaction',
  CHANNEL_CODE STRING COMMENT 'rep, adfa, opz, msl, spkr or pr',
  INTERACTION_TYPE STRING COMMENT 'Direct call, ADFA visit, Opz Sales call, MSL visit, Speaker program or PR visit',
  POVO_DISCUSSED BOOLEAN COMMENT 'True when POVO was discussed',
  SUMMARY STRING COMMENT 'One-line summary of the interaction'
) USING DELTA
CLUSTER BY (TERRITORY_ID)
COMMENT 'Interactions with HCPs across all teams. Logical key INTERACTION_ID.';

CREATE TABLE IF NOT EXISTS ${catalog}.${bronze_schema}.FCT_POVO_ACTIVITY (
  ACTIVITY_ID STRING NOT NULL COMMENT 'Activity key',
  TERRITORY_ID STRING COMMENT 'Territory',
  HCP_ID STRING COMMENT 'Prescriber',
  PATIENT_KEY STRING COMMENT 'Anonymised patient token; never PHI',
  EVENT_DATE DATE COMMENT 'Date of the event',
  EVENT_TYPE STRING COMMENT 'PEF (enrollment form), NRX (new script) or NEW_PATIENT (first paid script)'
) USING DELTA
CLUSTER BY (TERRITORY_ID)
COMMENT 'POVO patient funnel events. Logical key ACTIVITY_ID.';

CREATE TABLE IF NOT EXISTS ${catalog}.${bronze_schema}.FCT_TERRITORY_GOAL (
  TERRITORY_ID STRING NOT NULL COMMENT 'Territory',
  GOAL_YEAR INT NOT NULL COMMENT 'Goal year',
  GOAL_MONTH INT NOT NULL COMMENT 'Goal month, 1 to 12',
  METRIC_CODE STRING NOT NULL COMMENT 'PEF, NRX or NEW_PATIENTS',
  GOAL_VALUE INT COMMENT 'Goal for the month'
) USING DELTA
COMMENT 'Monthly territory goals. Logical key TERRITORY_ID + GOAL_YEAR + GOAL_MONTH + METRIC_CODE.';

CREATE TABLE IF NOT EXISTS ${catalog}.${bronze_schema}.REF_US_HOLIDAY (
  HOLIDAY_DATE DATE NOT NULL COMMENT 'Observed holiday date',
  HOLIDAY_NAME STRING COMMENT 'Holiday name'
) USING DELTA
COMMENT 'Company US holidays; working days are weekdays minus these. Logical key HOLIDAY_DATE.';

CREATE TABLE IF NOT EXISTS ${catalog}.${bronze_schema}.REF_TALKING_POINT (
  POINT_ID STRING NOT NULL COMMENT 'Talking point key',
  CONTENT_VERSION STRING COMMENT 'Content version, part of the AI cache key',
  CATEGORY STRING COMMENT 'messaging, objection or closing',
  VARIANT STRING COMMENT 'initial, next_call, extra or peer',
  PILLAR STRING COMMENT 'Pillar label for messaging, e.g. Efficacy',
  AUDIENCE STRING COMMENT 'HCP, NP, PA or ALL',
  SEGMENT_CODE STRING COMMENT 'imm, conv, exp or ALL',
  WRITER_STATE STRING COMMENT 'writer, non_writer or ALL',
  TEXT_TEMPLATE STRING COMMENT 'MLR-approved text with {snake_case} placeholders',
  DETAIL_TEMPLATE STRING COMMENT 'Insight or response template',
  NEXT_CALL_TEMPLATE STRING COMMENT 'Next-call variant template',
  SORT_ORDER INT COMMENT 'Default order',
  MLR_CODE STRING COMMENT 'MLR approval code',
  IS_ACTIVE BOOLEAN COMMENT 'False hides the point'
) USING DELTA
COMMENT 'Approved talking points (copied from seed/content/talking_points.json). Logical key POINT_ID.';

CREATE TABLE IF NOT EXISTS ${catalog}.${bronze_schema}.REF_OBJECTION_RULE (
  RULE_ID STRING NOT NULL COMMENT 'Rule key',
  AUDIENCE STRING COMMENT 'HCP, NP, PA or ALL',
  SEGMENT_CODE STRING COMMENT 'imm, conv, exp or ALL',
  MIN_DECILE INT COMMENT 'Lowest decile the rule applies to',
  MAX_DECILE INT COMMENT 'Highest decile the rule applies to',
  WRITER_STATE STRING COMMENT 'writer, non_writer or ALL',
  OBJECTION_POINT_IDS STRING COMMENT 'Ordered comma-separated POINT_IDs',
  PRIORITY INT COMMENT 'Lowest priority wins when several rules match'
) USING DELTA
COMMENT 'Which objections to show for a participant (copied from seed/content/objection_rules.json). Logical key RULE_ID.';

CREATE TABLE IF NOT EXISTS ${catalog}.${bronze_schema}.REF_COMPLIANCE_RULE (
  RULE_ID STRING NOT NULL COMMENT 'Rule key, e.g. off or claim',
  CHIP_LABEL STRING COMMENT 'Short chip label',
  TITLE STRING COMMENT 'Rule title',
  SEVERITY STRING COMMENT 'high, med or low',
  DEDUCTION INT COMMENT 'Points deducted from 100 when the rule fires',
  PATTERN STRING COMMENT 'Python regular expression, case-insensitive',
  SUPPRESS_PATTERN STRING COMMENT 'Regular expression that suppresses the rule; nullable',
  WHY_TEXT STRING COMMENT 'Why the note was flagged',
  FIX_TEXT STRING COMMENT 'How to fix it',
  SORT_ORDER INT COMMENT 'Display order',
  IS_ACTIVE BOOLEAN COMMENT 'False disables the rule'
) USING DELTA
COMMENT 'Compliance rules for post-call notes (copied from seed/content/compliance_rules.json). Logical key RULE_ID.';

CREATE TABLE IF NOT EXISTS ${catalog}.${bronze_schema}.REF_COMPLIANCE_TEXT (
  TEXT_ID STRING NOT NULL COMMENT 'Text key, e.g. TPL_MESSAGING',
  CONTENT_VERSION STRING COMMENT 'Content version, e.g. 2026.2',
  KIND STRING COMMENT 'template, replacement, reword or cut_off',
  TEXT_KEY STRING COMMENT 'Category (template), rule id (replacement), rule id (reword) or why/fix/placeholder (cut_off)',
  PATTERN STRING COMMENT 'Python regular expression for a reword; nullable',
  TEXT_TEMPLATE STRING COMMENT 'The text; {who} is the participant name',
  SORT_ORDER INT COMMENT 'Order',
  IS_ACTIVE BOOLEAN COMMENT 'False disables the text'
) USING DELTA
COMMENT 'Wording of the compliance rewrite (copied from seed/content/compliance_texts.json). Logical key TEXT_ID.';
